for line in _mem['s12']['content'].strip().splitlines():
    line = line.strip()
    if line.startswith('- '):
        entry = line[2:].strip()
        if ' by ' in entry:
            title, artist = entry.rsplit(' by ', 1)
            archive_songs.add((title.strip(), artist.strip()))

# Build a lookup: for each song_id, check if it matches any archive entry
matches_by_playlist = {}  # playlist_id -> list of song_ids to remove
unique_matched_song_ids = set()

for pl_id, song_ids in playlist_song_ids.items():
    matches = []
    for sid in song_ids:
        title, artists = song_details[sid]
        # Check if any archive entry matches this song
        for (arch_title, arch_artist) in archive_songs:
            if title == arch_title and arch_artist in artists:
                matches.append(sid)
                unique_matched_song_ids.add(sid)
                break
    if matches:
        matches_by_playlist[pl_id] = matches
        print(f"Playlist {pl_id}: {len(matches)} matches -> {matches}")
    else:
        print(f"Playlist {pl_id}: no matches")

print(f"Total unique matched songs: {len(unique_matched_song_ids)}")

